import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.BzGQ_3Jc.js";const p=JSON.parse('{"title":"12 测试验收","description":"","frontmatter":{},"headers":[],"relativePath":"12_测试验收.md","filePath":"12_测试验收.md","lastUpdated":1788436019000}'),a={name:"12_测试验收.md"};function i(c,t,n,l,h,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="_12-测试验收" tabindex="-1">12 测试验收 <a class="header-anchor" href="#_12-测试验收" aria-label="Permalink to &quot;12 测试验收&quot;">​</a></h1><blockquote><p>文档版本：1.1.6</p></blockquote><p>对接完成后按本页自测。官方 Demo 仅用于对照，<strong>不要把 Demo 的广告位 ID 写进正式包</strong>。</p><p>按本页必测项自测即可。</p><hr><h2 id="_1-必测项" tabindex="-1">1. 必测项 <a class="header-anchor" href="#_1-必测项" aria-label="Permalink to &quot;1. 必测项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>通过标准</th></tr></thead><tbody><tr><td>Init</td><td>主进程 / <code>didFinishLaunching</code> 调用一次；日志有初始化成功；空 AppId 收到 <code>onFailed</code>（1001），不闪退</td></tr><tr><td>激励</td><td>Load 成功 → <code>entryAdScenario</code> → Show → 播完 <code>onAdReward</code> → 关闭</td></tr><tr><td>插屏</td><td>同上，无 Reward</td></tr><tr><td>开屏</td><td>全屏容器；<code>onAdClosed</code> / <code>onAdShowFailed</code> 后进首页</td></tr><tr><td>Banner</td><td>顶/底展示完整；JinDai 容器 ≥200dp；关闭后从容器移除</td></tr><tr><td>原生模板</td><td><code>renderType=1</code>，不要自拼布局</td></tr><tr><td>原生自渲染</td><td><code>renderType=2</code>；Show <strong>前</strong>拼装并打 TAG；主图 TAG=<code>td_image</code>；iOS Label <code>userInteractionEnabled=YES</code></td></tr><tr><td>Load ≠ Show</td><td><code>onAdLoaded</code> 后容器仍空（或仅占位），点 Show 才出现广告</td></tr><tr><td>隐私默认</td><td><strong>不调</strong> <code>setPrivacyUserAgree</code> 也能出广告（默认开）</td></tr><tr><td>关闭个性化</td><td><code>setPrivacyUserAgree(false)</code> 后不再出个性化广告</td></tr><tr><td>OAID / IDFA</td><td>JinDai、AdGain 无设备标识时可能无填充；Android 等 OAID 回写后再 Load</td></tr><tr><td>失败重试</td><td>失败后不立刻 <code>loadAd</code></td></tr><tr><td>当前广告</td><td>Load 成功后 <code>getAdInfo()</code> 有值</td></tr><tr><td>释放</td><td>离开页面 <code>onDestroy</code>；destroy 后再 Load/Show 收到 1001</td></tr></tbody></table><hr><h2 id="_2-联调环境" tabindex="-1">2. 联调环境 <a class="header-anchor" href="#_2-联调环境" aria-label="Permalink to &quot;2. 联调环境&quot;">​</a></h2><ul><li>用你们后台自己的 App ID、广告位 ID。</li><li>真机优先。模拟器上 OAID / IDFA / 部分源可能无填充。</li><li>冷启动开屏：等 Init 成功再 Load。</li><li>看 Logcat / Xcode 控制台里 TD 与各源的失败原因。</li></ul><hr><h2 id="_3-官方-demo-对照-仅内部联调" tabindex="-1">3. 官方 Demo 对照（仅内部联调） <a class="header-anchor" href="#_3-官方-demo-对照-仅内部联调" aria-label="Permalink to &quot;3. 官方 Demo 对照（仅内部联调）&quot;">​</a></h2><p>官方 Demo（对照用，正式包不要抄里面的广告位 ID）：</p><ul><li>Android：<a href="https://github.com/tydeonj/td-sdk-demo-android" target="_blank" rel="noreferrer">https://github.com/tydeonj/td-sdk-demo-android</a></li><li>iOS：<a href="https://github.com/tydeonj/td-sdk-demo-ios" target="_blank" rel="noreferrer">https://github.com/tydeonj/td-sdk-demo-ios</a></li></ul><p>Demo 行为约定：</p><ul><li>隐私开关默认开，与 SDK 默认一致。</li><li>原生自渲染在点 Show 时拼装，不在 <code>onAdLoaded</code> 里拼。</li></ul><hr><h2 id="_4-常见验收失败对照" tabindex="-1">4. 常见验收失败对照 <a class="header-anchor" href="#_4-常见验收失败对照" aria-label="Permalink to &quot;4. 常见验收失败对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>先看</th></tr></thead><tbody><tr><td>一直无填充</td><td><a href="./04_初始化与隐私">04</a> 四门与 OAID/IDFA；<a href="./01_后台配置">01</a> 广告源</td></tr><tr><td><code>1007</code> / adapter 缺失</td><td><a href="./02_Android集成">02</a> / <a href="./03_iOS集成">03</a> 是否加了对应模块</td></tr><tr><td><code>1023</code> 频次达限</td><td>本轮被后台频次拦住（混有 ADN 失败时整轮仍是 1023）。稍后重试 <code>loadAd</code>，不要立刻连点</td></tr><tr><td>原生点了没反应、没图</td><td><a href="./09_原生广告">09</a> TAG 与主图</td></tr><tr><td>Load 后立刻看到文案</td><td>不要在 <code>onAdLoaded</code> 里拼装或 Show</td></tr><tr><td>开屏进不了首页</td><td>必须在 Closed / ShowFailed 里收起 overlay</td></tr></tbody></table>',19)])])}const A=d(a,[["render",i]]);export{p as __pageData,A as default};
